css:
.button-container {
  height: 75px;
  width: 260px;
}
.button {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  padding: 0px;
  border-top: 2px double rgba(255, 255, 255, 0.573);
  border-bottom: none;
  border-left: 2px outset rgba(0, 0, 0, 0.494);
  border-right: 2px solid rgba(233, 79, 202, 0.7);
  border-radius: 50px;
  filter: hue-rotate(-15deg) drop-shadow(rgba(0, 0, 0, 0.157) 0px 30px 10px)
    saturate(2);
  font-family: "poppins ", sans-serif;
  background: linear-gradient(
    64.14deg,
    rgb(59, 130, 246) 0%,
    rgb(91, 142, 247) 10%,
    rgb(139, 92, 246) 25%,
    rgb(167, 143, 247) 40%,
    rgb(184, 124, 246) 50%,
    rgb(201, 111, 245) 60%,
    rgb(236, 72, 153) 75%,
    rgb(240, 96, 168) 85%,
    rgb(234, 91, 163) 92%,
    rgb(59, 130, 246) 100%
  );
  transition:
    transform 0.6s cubic-bezier(0.22, 1, 0.36, 1),
    filter 0.8s ease,
    box-shadow 0.8s ease;
  transform: scale(1);
  box-sizing: border-box;
  animation: hue-rotate 6s linear infinite;
}
@keyframes hue-rotate {
  from {
    filter: hue-rotate(0deg) drop-shadow(rgba(0, 0, 0, 0.157) 0px 30px 10px)
      saturate(2);
  }
  to {
    filter: hue-rotate(360deg) drop-shadow(rgba(0, 0, 0, 0.157) 0px 30px 10px)
      saturate(2);
  }
}
.button:hover {
  transform: scale(1.02);
  filter: hue-rotate(120deg) drop-shadow(0 18px 28px rgba(0, 0, 0, 0.25))
    saturate(2.1);
}
.button .bg-div-2 {
  transition:
    box-shadow 0.9s ease,
    filter 0.9s ease;
}
.button:hover .bg-div-2 {
  box-shadow:
    inset 0 0 14px rgba(255, 255, 255, 0.25),
    inset 0 0 24px rgba(255, 120, 200, 0.35);
  filter: brightness(1.12);
}
.button:active {
  transform: scale(0.96);
  filter: hue-rotate(140deg) drop-shadow(0 10px 16px rgba(0, 0, 0, 0.25))
    saturate(2.2);
}
.button:hover .text-two p span {
  animation-duration: 1.9s;
}
.text-one {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 32px 48px;
  opacity: 0;
  pointer-events: none;
}

.bg-div {
  z-index: 90;
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
}

.bg-inn-1 {
  position: absolute;
  border-radius: 9999px;
  filter: blur(3px) drop-shadow(-2px 0 3px #ffffff);
  left: 25.6px;
  top: 3.2px;
  width: 160px;
  height: 16px;
  background: linear-gradient(
    to right,
    rgba(255, 255, 255, 0.868) 30%,
    transparent 100%
  );
}

.bg-inn-2 {
  position: absolute;
  border-radius: 9999px;
  left: 40px;
  top: 32px;
  width: 64px;
  height: 32px;
  background: radial-gradient(
    circle,
    rgba(255, 255, 255, 1) 0%,
    rgba(255, 255, 255, 0) 70%
  );
  filter: drop-shadow(-10px 10px 3px #d277cc);
}

.bg-inn-3 {
  position: absolute;
  border-radius: 9999px;
  left: 160px;
  top: 8px;
  width: 80px;
  height: 80px;
  background: radial-gradient(
    circle,
    rgba(255, 255, 255, 1) 0%,
    rgba(255, 255, 255, 0) 50%
  );
  filter: drop-shadow(-5px -5px 7px #ff5500b4);
}

.bg-inn-4 {
  position: absolute;
  border-radius: 9999px;
  left: 272px;
  top: 16px;
  width: 54.4px;
  height: 64px;
  background: radial-gradient(
    circle,
    rgba(255, 255, 255, 1) 0%,
    transparent 70%
  );
  filter: drop-shadow(-1px 0 30px #ff002f);
}

.bg-inn-5 {
  position: absolute;
  border-radius: 9999px;
  top: 8px;
  width: 100%;
  height: 11.2px;
  background: radial-gradient(
    circle,
    rgba(255, 255, 255, 0.293) 30%,
    rgba(255, 181, 21, 0.164) 50%,
    rgba(234, 44, 255, 0.419) 60%,
    rgba(255, 255, 255, 0) 90%
  );
