.bg-inn-6 {
  position: absolute;
  border-radius: 9999px;
  left: 281.6px;
  top: -1.6px;
  width: 32px;
  height: 32px;
  background: radial-gradient(
    circle,
    rgba(255, 255, 255, 1) 0%,
    rgba(255, 255, 255, 0) 70%
  );
}

.bg-inn-7 {
  position: absolute;
  border-radius: 9999px;
  left: 121.6px;
  transform: rotate(-35deg);
  top: -32px;
  width: 32px;
  height: 80px;
  background: radial-gradient(
    circle,
    rgba(255, 255, 255, 0.614) 0%,
    #fd87602d 60%,
    rgba(255, 255, 255, 0) 100%
