}

.bg-inn-8 {
  position: absolute;
  border-radius: 9999px;
  left: 88px;
  top: -16px;
  width: 48px;
  height: 48px;
  background: radial-gradient(
    circle,
    rgba(255, 255, 255, 0.614) 0%,
    rgba(255, 255, 255, 0) 80%
  );
}

.bg-inn-9 {
  position: absolute;
  border-radius: 9999px;
  filter: blur(1px) drop-shadow(0px 0 3px #ffffff);
  left: 8px;
  bottom: 22.4px;
  width: 100%;
  height: 1.6px;
  background: radial-gradient(
    circle,
    rgba(255, 255, 255, 1) 50%,
    rgba(255, 255, 255, 0) 90%
  );
}

.bg-inn-10 {
  position: absolute;
  border-radius: 9999px;
  filter: blur(1px) drop-shadow(0px 0 3px #ffffff);
  left: 4.8px;
  top: 16px;
  width: 16px;
  height: 48px;
  border-top: 1px solid white;
  border-right: 1px solid white;
  background: linear-gradient(
    to bottom,
    rgba(255, 255, 255, 0.419) 0%,
    transparent 50%
  );
}

.bg-inn-11 {
  position: absolute;
  border-radius: 100%;
  filter: blur(4px) drop-shadow(0px -10px 10px #ff5107fb);
  left: 192px;
  top: 56px;
  width: 80px;
  height: 28.8px;
  background: radial-gradient(
    circle,
    rgba(255, 255, 255, 0.773) 10%,
    rgba(255, 255, 255, 0.159) 60%
  );
}

.bg-inn-12 {
  position: absolute;
  border-radius: 9999px;
  filter: blur(2px) drop-shadow(0px -10px 10px #f36b9d);
  left: 176px;
  top: 17.6px;
  width: 96px;
  height: 4.8px;
  background: radial-gradient(
    circle,
    rgba(255, 255, 255, 0.973) 30%,
    rgba(255, 255, 255, 0.159) 100%
  );
}

.bg-inn-13 {
  position: absolute;
  border-radius: 9999px;
  filter: blur(3px) drop-shadow(-15px 0 5px #f8283d9e);
  left: 128px;
  top: 59.2px;
  width: 88px;
  height: 27.2px;
  background: radial-gradient(
    circle,
    rgba(255, 255, 255, 0.762) 10%,
    rgba(255, 255, 255, 0.159) 70%
  );
}

.bg-inn-14 {
  position: absolute;
  border-radius: 9999px;
  filter: blur(1px) drop-shadow(10px -10px 10px #6f0424);
  transform: rotate(-35deg);
  left: 8px;
  bottom: 4.8px;
  width: 8px;
  height: 19.2px;
  background: radial-gradient(
    circle,
    rgba(255, 255, 255, 0.848) 0%,
    rgba(255, 255, 255, 0.159) 60%
  );
}

.text-two {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 90;

  font-family: "poppins", sans-serif;
  font-weight: 800;
  font-size: 25px;

  color: rgba(255, 255, 255, 0.85);
  text-shadow:
    0 1px 2px rgba(0, 0, 0, 0.35),
    0 0 6px rgba(255, 255, 255, 0.35),
    0 0 18px rgba(255, 255, 255, 0.25);

  backdrop-filter: blur(1.5px);
  -webkit-backdrop-filter: blur(1.5px);
  mix-blend-mode: normal;
}
.text-two p {
  font-family: "poppins", sans-serif;
  font-weight: 900;
  font-size: 20px;
  color: #180707a2;
  letter-spacing: 3px;
  /* -webkit-text-stroke: 1.5px rgb(73, 40, 40);
  text-stroke: 1.5px rgb(255, 255, 255); */
  text-shadow: 0 0 6px rgba(255, 255, 255, 0.2);
  display: inline-flex;
}

.text-two p span {
  display: inline-block;
  --i: 0;
  filter: url(#liquid);
  transition: transform 0.4s ease;
}
.text-two p span {
  animation: liquidMove 2.2s ease-in-out infinite;
  animation-delay: calc(var(--i) * 0.1s);
}
@keyframes liquidMove {
  0% {
    transform: translate(0, 0) skewX(0deg);
  }
  25% {
    transform: translate(1px, -2px) skewX(-4deg);
  }
  50% {
    transform: translate(-1px, 2px) skewX(4deg);
  }
  75% {
    transform: translate(1px, 1px) skewX(-2deg);
  }
  100% {
    transform: translate(0, 0) skewX(0deg);
  }
}
.bg-div-2 {
  z-index: 10;
  position: absolute;
  inset: 4px;
  display: flex;
  border: double 2px rgba(255, 255, 255, 0.263);
  backdrop-filter: blur(2px);
  filter: blur(1px) brightness(1.1) saturate(50%) hue-rotate(30deg);
  border-radius: 47px;
  width: calc(100% - 8px);
  height: calc(100% - 8px);
  padding: 16px;
  background-color: #ffffff1c;
  background-origin: content-box;
  background-clip: content-box, border-box;
  box-shadow: inset 0 0 10px #a84fd88d;
}

.bg-div-3 {
  z-index: 10;
  display: flex;
  border-left: 1px solid rgba(255, 255, 255, 0.564);
  border-right: 1px solid rgb(255, 255, 255);
  backdrop-filter: blur(40px);
  box-shadow: inset 0 0 20px rgba(246, 142, 213, 0.86);
  -webkit-backdrop-filter: blur(5px);
  border-radius: 31px;
  width: 100%;
  height: 100%;
  background-origin: border-box;
  background-clip: content-box, border-box;
  filter: brightness(140%);
}
.font-family {
  font-family: "poppins ", sans-serif;
}
